SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷一百十八", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/b0cccc4999dc32c7b4789dd00c3df5fb28149a70/content/books/zizhi-tongjian/vol-294/year-0958/part-04/sources/library/jiuwudaishi-118-april-958/source.txt", "note": "《旧五代史》卷一百十八，段落 jiu-wudaishi-205deb4a7860-p002784；EPUB电子本，纸本及异文待核", "id": "ecd54a46-a942-5fe1-a449-14d39670c041"}, {"title": "旧五代史·卷一百十八", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/b0cccc4999dc32c7b4789dd00c3df5fb28149a70/content/books/zizhi-tongjian/vol-294/year-0958/part-04/sources/library/jiuwudaishi-118-may-958/source.txt", "note": "《旧五代史》卷一百十八，段落 jiu-wudaishi-205deb4a7860-p002785；EPUB电子本，纸本及异文待核", "id": "5a92c469-806c-5112-9fc2-bfb6fd3d0919"}, {"title": "资治通鉴·后周纪五", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/974130947fcdb1b84376e825c816bafd1322500d/content/books/zizhi-tongjian/vol-294/year-0958/part-03/sources/library/tongjian-294-958-peace-settlement/source.txt", "note": "《资治通鉴》后周纪五，段落 zizhi-tongjian-a63549944a71-p003488；电子底本待考，分段待核", "id": "fe823f81-8497-5757-97b7-d180f0448c0c"}, {"title": "旧五代史·卷一百十八", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/974130947fcdb1b84376e825c816bafd1322500d/content/books/zizhi-tongjian/vol-294/year-0958/part-03/sources/library/jiuwudaishi-118-march-peace-gifts/source.txt", "note": "《旧五代史》卷一百十八，段落 jiu-wudaishi-205deb4a7860-p002783；EPUB电子本，纸本及异文待核", "id": "0ee064de-d661-5620-87f4-9b91cc1160af"}, {"title": "新五代史·卷六十二", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/974130947fcdb1b84376e825c816bafd1322500d/content/books/zizhi-tongjian/vol-294/year-0958/part-03/sources/library/xinwudaishi-62-jiangbei-settlement/source.txt", "note": "《新五代史》卷六十二，段落 xin-wudaishi-b08f244b9241-p003154；EPUB电子本，纸本及异文待核", "id": "7c258e79-23d8-5e03-b061-26accc0b0d19"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "柴荣", "aliases": ["郭荣", "柴榮", "郭榮"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本姓柴，950年《资治通鉴》以郭荣记名，任贵州刺史、天雄牙内都指挥使。父亲柴守礼是郭威妻子柴氏的兄长，郭威在尚无儿子时收养他。《新五代史》记他幼年跟随姑母在郭威家成长。《旧五代史》的任职纪年与通鉴不同，分别保留。", "biography": null, "status": "draft", "id": "697c1a4f-b373-5a78-8b47-330fe349a424"}, {"name": "李璟", "aliases": ["徐景通", "景通", "李景"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：李璟。", "biography": null, "status": "draft", "id": "6bf72971-88c3-5187-8f25-98cde2a9554a"}, {"name": "徐辽", "aliases": ["徐遼"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐临汝公。958年李璟派他代自己到后周行营上寿，《旧五代史》还记翌月献寿觞和多类礼物。具体家世、生卒年未载，不因徐姓猜定其父母。", "biography": null, "status": "draft", "id": "61dbd46b-a983-5167-8629-1273b4f974e5"}, {"name": "钱弘俶", "aliases": ["钱俶", "錢俶", "錢弘俶"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "钱传瓘之子，母亲吴氏。《宋史》本传明确本名弘俶，后名钱俶；《资治通鉴》所用电子本在王室家属追述中把俶写作拆分字形。生卒年暂未录全。", "biography": null, "status": "draft", "id": "3a65648c-82a5-5d66-be49-1fbc1ccb4e70"}, {"name": "张永德", "aliases": ["張永德"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "阳曲人，郭威的女婿。950年任供奉官押班，奉命给昭义节度使常思送生日礼物；常思接到杀他的密诏后拘留观望，郭威取京师后释放并道歉。生卒年本批未录。", "biography": null, "status": "draft", "id": "c1584e5c-2a3c-5c28-bbe4-7c8a05161c51"}, {"name": "赵匡胤", "aliases": ["趙匡胤"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周宿卫将领，后来成为宋太祖。954年高平之战右军溃逃后，与张永德分率两翼反击北汉军。《宋史》本纪印证其率同列冲锋的记载。生卒年留待相应史料补录。", "biography": null, "status": "draft", "id": "ce0fe2a6-d446-50c7-b968-4245fd9693ad"}, {"name": "安审琦", "aliases": ["安審琦"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：安审琦，彰圣都指挥使、领顺化节度使者。", "biography": null, "status": "draft", "id": "a579a6a1-65a5-5c8a-9c6c-be178cb049aa"}, {"name": "郭崇", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周侍卫马军都指挥使。952年郭威亲征兖州时，充在京都巡检。生卒年尚未录入。", "biography": null, "status": "draft", "id": "da797339-8eeb-5a3d-aa29-97f251a5943c"}, {"name": "冯延巳", "aliases": ["馮延巳", "冯延己", "馮延己", "冯延已"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐官员，曾任驾部郎中、齐王元帅府常书记。《资治通鉴》本段作冯延己及延已，《新五代史》作冯延巳；据同一南唐政局、陈觉及常梦锡等对应关系校核为同人，展示采用冯延巳，原文异体保留。生卒年尚未核。", "biography": null, "status": "draft", "id": "0b3ed4d7-1a4c-50a5-ad65-aee4b82089ba"}, {"name": "严续", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷270贞明四年条所见人物：严续。", "biography": null, "status": "draft", "id": "57b5cb9f-cb31-5e6a-87de-6363e1836468"}, {"name": "陈觉", "aliases": ["陳覺"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：陈觉，海陵人、参与谈议者。", "biography": null, "status": "draft", "id": "8f8c34eb-c238-596f-a688-8b8332b405a1"}, {"name": "常梦锡", "aliases": ["常夢錫"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐官员，万年人。941年四月与陈觉一起被李昪任命为宣徽副使。生卒年未据本段确定。", "biography": null, "status": "draft", "id": "9eaabd48-0b3a-5cc3-a5ec-f9107c987328"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

