SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "description", "claim_text": "柴荣命为杨行密、徐温等墓配守户，照看江北南唐臣僚祖墓。", "citation": "卷294·显德五年（958年三月至五月及相关追述）·zztj-v294-y0958-p025·原文件第30行", "note": "原文：庚戌，敕故淮南节度使杨行密、故升府节度使徐温等墓并量给守户。其江南群臣墓在江北者，亦委长吏以时检校。；核对说明：杨行密徐温均已故，未列为在场参与者；检校在这里是照看检查，不是授检校官衔。", "status": "draft", "id": "9eb40d5a-5d28-59b4-ad42-528299730774", "subject_id": "c7ac9c9c-12dd-5381-ad98-4ddbdeb83a37", "source_id": "fe823f81-8497-5757-97b7-d180f0448c0c"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "958年三月庚戌", "citation": "卷294·显德五年（958年三月至五月及相关追述）·zztj-v294-y0958-p025·原文件第30行", "note": "原文：庚戌，敕故淮南节度使杨行密、故升府节度使徐温等墓并量给守户。其江南群臣墓在江北者，亦委长吏以时检校。；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "00e95003-1917-5f95-a206-ddc69f8c237c", "subject_id": "c7ac9c9c-12dd-5381-ad98-4ddbdeb83a37", "source_id": "fe823f81-8497-5757-97b7-d180f0448c0c"}, {"subject_table": "person", "field_path": "description", "claim_text": "柴荣：命地方官配守户、定期照看有关坟墓。", "citation": "卷294·显德五年（958年三月至五月及相关追述）·zztj-v294-y0958-p025·原文件第30行", "note": "原文：庚戌，敕故淮南节度使杨行密、故升府节度使徐温等墓并量给守户。其江南群臣墓在江北者，亦委长吏以时检校。；核对说明：核对同名、职务及行动后识别主体；展示简体，摘录保留原字。", "status": "draft", "id": "eedc3cf9-02e3-5dd8-ab32-a67ac29cf10c", "subject_id": "697c1a4f-b373-5a78-8b47-330fe349a424", "source_id": "fe823f81-8497-5757-97b7-d180f0448c0c"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "柴荣：命地方官配守户、定期照看有关坟墓。", "citation": "卷294·显德五年（958年三月至五月及相关追述）·zztj-v294-y0958-p025·原文件第30行", "note": "原文：庚戌，敕故淮南节度使杨行密、故升府节度使徐温等墓并量给守户。其江南群臣墓在江北者，亦委长吏以时检校。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "60318190-1839-558c-b007-d7a910a57788", "subject_id": "7e214459-881c-5268-9d53-89977abb7102", "source_id": "fe823f81-8497-5757-97b7-d180f0448c0c"}, {"subject_table": "event", "field_path": "description", "claim_text": "《旧五代史》同日明确先代坟墓照看。", "citation": "《旧五代史》卷一百十八，段落 jiu-wudaishi-205deb4a7860-p002783；EPUB电子本，纸本及异文待核", "note": "原文：庚戌，詔：「故淮南節度使楊行密、故升府節度使徐溫各給守冢戶，應江南臣僚有先代墳墓在江北者，委所在長吏差人檢校。」；核对说明：守户未记数量，不能自定每墓两户或土地面积。", "status": "draft", "id": "59349adf-2e9f-5f46-9b26-ae693c41db10", "subject_id": "c7ac9c9c-12dd-5381-ad98-4ddbdeb83a37", "source_id": "0ee064de-d661-5620-87f4-9b91cc1160af"}, {"subject_table": "event", "field_path": "description", "claim_text": "李璟派临汝公徐辽代向柴荣祝寿。", "citation": "卷294·显德五年（958年三月至五月及相关追述）·zztj-v294-y0958-p026·原文件第31行", "note": "原文：辛亥，唐主遣其临汝公徐辽代己来上寿。；核对说明：上寿是礼仪出使，不凭这一派遣日推定柴荣生日。", "status": "draft", "id": "88b808ef-3710-5cc6-b4a0-3adce9a3c603", "subject_id": "caae40f6-67ef-58d3-82e1-6380dce4a86b", "source_id": "fe823f81-8497-5757-97b7-d180f0448c0c"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "958年三月辛亥派遣，抵达行礼日未在本句独载", "citation": "卷294·显德五年（958年三月至五月及相关追述）·zztj-v294-y0958-p026·原文件第31行", "note": "原文：辛亥，唐主遣其临汝公徐辽代己来上寿。；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "7eadfad7-ed9e-5604-838b-56c4940a4ad0", "subject_id": "caae40f6-67ef-58d3-82e1-6380dce4a86b", "source_id": "fe823f81-8497-5757-97b7-d180f0448c0c"}, {"subject_table": "person", "field_path": "description", "claim_text": "李璟：派徐辽代表自己上寿。", "citation": "卷294·显德五年（958年三月至五月及相关追述）·zztj-v294-y0958-p026·原文件第31行", "note": "原文：辛亥，唐主遣其临汝公徐辽代己来上寿。；核对说明：核对同名、职务及行动后识别主体；展示简体，摘录保留原字。", "status": "draft", "id": "a9f1afa1-c4ca-5e9a-89fc-e1a7b9a9235a", "subject_id": "6bf72971-88c3-5187-8f25-98cde2a9554a", "source_id": "fe823f81-8497-5757-97b7-d180f0448c0c"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "李璟：派徐辽代表自己上寿。", "citation": "卷294·显德五年（958年三月至五月及相关追述）·zztj-v294-y0958-p026·原文件第31行", "note": "原文：辛亥，唐主遣其临汝公徐辽代己来上寿。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "cb8dec51-6d02-5680-b52e-f5c724ac7b78", "subject_id": "59dfcfad-816d-52b0-b42f-1cfa41b6ba20", "source_id": "fe823f81-8497-5757-97b7-d180f0448c0c"}, {"subject_table": "person", "field_path": "description", "claim_text": "徐辽：受派赴周代表李璟祝寿。", "citation": "卷294·显德五年（958年三月至五月及相关追述）·zztj-v294-y0958-p026·原文件第31行", "note": "原文：辛亥，唐主遣其临汝公徐辽代己来上寿。；核对说明：核对同名、职务及行动后识别主体；展示简体，摘录保留原字。", "status": "draft", "id": "b992709b-2b55-558d-b70e-f6bd0101c9b1", "subject_id": "61dbd46b-a983-5167-8629-1273b4f974e5", "source_id": "fe823f81-8497-5757-97b7-d180f0448c0c"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "徐辽：受派赴周代表李璟祝寿。", "citation": "卷294·显德五年（958年三月至五月及相关追述）·zztj-v294-y0958-p026·原文件第31行", "note": "原文：辛亥，唐主遣其临汝公徐辽代己来上寿。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "01ade5ac-452f-5ad3-80aa-e22408125ca8", "subject_id": "6aad7906-e986-5991-9841-eaa95702fd26", "source_id": "fe823f81-8497-5757-97b7-d180f0448c0c"}, {"subject_table": "event", "field_path": "description", "claim_text": "《旧五代史》同日补记买宴钱二百万、伶官五十人随行。", "citation": "《旧五代史》卷一百十八，段落 jiu-wudaishi-205deb4a7860-p002783；EPUB电子本，纸本及异文待核", "note": "原文：辛亥，李景遣所署臨汝郡公徐遼進買宴錢二百萬並遣伶官五十人與遼俱來獻壽觴。；核对说明：钱单位只按原称，不补现代价值；随行总人数不直接等于五十一，其他人员未载。", "status": "draft", "id": "b0bf92cb-b514-5bd9-acf8-0ee0034f8e74", "subject_id": "caae40f6-67ef-58d3-82e1-6380dce4a86b", "source_id": "0ee064de-d661-5620-87f4-9b91cc1160af"}, {"subject_table": "event", "field_path": "description", "claim_text": "《旧五代史》另记四月癸丑行宫宴会，徐辽代李璟献寿觞。", "citation": "《旧五代史》卷一百十八，段落 jiu-wudaishi-205deb4a7860-p002784；EPUB电子本，纸本及异文待核", "note": "原文：夏四月癸丑，宴從臣及江南進奉使馮延巳等於行宮，徐遼代李景捧壽觴以獻，；核对说明：派遣与实际行礼分月记录，不压成三月辛亥已经到场；此时有冯延巳等使者，未凭等字补全名单。", "status": "draft", "id": "223ace86-2c20-53a9-ae51-e7bb4632769b", "subject_id": "caae40f6-67ef-58d3-82e1-6380dce4a86b", "source_id": "ecd54a46-a942-5fe1-a449-14d39670c041"}, {"subject_table": "event", "field_path": "description", "claim_text": "后周疏浚汴口，导河水通淮，连通江淮舟路。", "citation": "卷294·显德五年（958年三月至五月及相关追述）·zztj-v294-y0958-p027·原文件第32行", "note": "原文：是月，浚汴口，导河流达于淮，于是江、淮舟楫始通。；核对说明：河指史载河流，不未经地理证据画现代水道；命浚与通航概述无精确完成日。", "status": "draft", "id": "fbaec3b4-3e41-5bb9-9d60-f54d51ac00e8", "subject_id": "dff4e042-aa00-514b-be00-5e05137f7e97